/** Their aliases, sorted as names are compared (by key, then as given). */
public List<String> getAliases() {
    return aliases.stream()
            .sorted(Comparator.comparing(PersonAlias::getAliasKey).thenComparing(PersonAlias::getAlias))
            .map(PersonAlias::getAlias).toList();
}

/** Whether they have the name, as names are compared, as an alias. */
public boolean hasAlias(String name) {
    String key = keyOf(name);
    return aliases.stream().anyMatch(a -> a.getAliasKey().equals(key));
}

public void addAlias(String alias) { aliases.add(new PersonAlias(sheetId, alias)); }

/**
 * Merge them into the other person: they name the other as merged into, and lose their aliases, holds
 * and contact. Returns their aliases, as given, in the order they were added.
 */
public List<String> mergeInto(Long otherId) {
    List<String> theirs = aliases.stream().map(PersonAlias::getAlias).toList();
    this.mergedInto = otherId;
    aliases.clear();
    holds.clear();
    this.contact = null;
    return theirs;
}

/** Move them to another sheet, noting the one they came from, with their grades, terms, contact, aliases and holds. */
public void transferTo(String sheetId) {
    this.transferredFrom = this.sheetId;
    this.sheetId = sheetId;
    List<PersonAlias> theirs = new ArrayList<>(aliases);
    aliases.clear();
    for (PersonAlias a : theirs) aliases.add(new PersonAlias(sheetId, a.getAlias()));
}

/** The sheet they were last transferred from, or null when never transferred. */
public String getTransferredFrom() { return transferredFrom; }

/** Their name and aliases, as given. */
public List<String> namesAndAliases() {
    List<String> all = new ArrayList<>();
    all.add(name);
    for (PersonAlias a : aliases) all.add(a.getAlias());
    return all;
}

/** The date they are retired from, or null while not retired. */
public LocalDate getRetiredFrom() { return retiredFrom; }

/** Retire them from the date, on the sheet's today. */
public void retireFrom(LocalDate retiredFrom, LocalDate on) {
    this.retiredFrom = retiredFrom;
    this.retiredOn = on;
}

public boolean isRetired() { return retiredFrom != null; }
public void moveTo(Long personId, long listed) {
    this.personId = personId;
    this.listed = listed;
}

/**
 * Move the claim, with its person, to another sheet: it keeps its status, dates, note, tags, frozen
 * figure and logs, but loses any figure a statement bound it to, its reference, its number (to be
 * given the other sheet's next), its settle batch and any editor's lock.
 */
public void transferTo(String sheetId) {
    this.sheetId = sheetId;
    this.stated = false;
    this.statedDue = null;
    bindings.clear();
    setRef(null);
    this.number = null;
    this.numberPeriod = null;
    this.numberSeq = null;
    this.settleBatch = null;
    this.lockedBy = null;
}

/** The sheet's today it was first opened on, as its status log records it; null when it records none. */
public LocalDate openedOn() {
    for (ClaimLogEntry line : log) if (line.getStatus() == ClaimStatus.OPEN) return line.getDate();
    return null;
}

public BigDecimal getAmount() { return amount; }

public void setAmount(BigDecimal amount) { this.amount = amount; }

public LocalDate getDate() { return date; }

public void setDate(LocalDate date) { this.date = date; }

public String getNote() { return note; }

/** The date it is due by, fixed when added; it does not move with its date or the terms, only when a holiday is added. */
public LocalDate getDueBy() { return dueBy; }

private void record(String event, String sheetId, String user, Person person, Claim claim) {
    record(event, sheetId, user, person, claim, claim.getNumber(), "");
}

/** A claim's audit line; one about a claim with a number has it, then any extra fields. */
private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
        String extra) {
    audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
            + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
            + (number != null ? " number=" + number : "") + extra);
}

/**
 * Take a person's claims, as they arrive with them from another sheet, onto the sheet (locked for
 * numbering by the caller): each loses what {@link Claim#transferTo} drops, and each that had a number
 * takes the sheet's next, in the order they were opened (by the sheet's today each was first opened on,
 * then in the order they were added). A correction, or a claim split off another, then names the
 * number its claim was given. Their tags are kept among those used on the sheet.
 */
@Transactional
public void receive(Sheet to, List<Claim> arriving) {
    Map<Long, String> old = new HashMap<>();
    for (Claim claim : arriving) {
        old.put(claim.getId(), claim.getNumber());
        claim.transferTo(to.getId());
    }
    claims.saveAllAndFlush(arriving);
    numberAfresh(to, arriving, old);
    for (Claim claim : arriving) keepTags(to.getId(), claim);
    claims.saveAllAndFlush(arriving);
}

/**
 * Number afresh, on the sheet (locked for numbering by the caller), the claims that had a number before
 * ({@code oldNumbers}, by claim id): each takes the sheet's next, in the order they were opened (by the
 * sheet's today each was first opened on, then in the order they were added). A correction, or a claim
 * split off another, then names the number its claim was given.
 */
@Transactional
public void numberAfresh(Sheet to, List<Claim> numbering, Map<Long, String> oldNumbers) {
    List<Claim> numbered = numbering.stream().filter(c -> oldNumbers.get(c.getId()) != null)
            .sorted(Comparator.comparing(Claim::openedOn,
                    Comparator.nullsFirst(Comparator.naturalOrder()))
                    .thenComparing(Claim::getId))
            .toList();
    Map<String, String> renumbered = new HashMap<>();
    for (Claim claim : numbered) {
        number(to, claim);
        claims.saveAndFlush(claim);
        renumbered.put(oldNumbers.get(claim.getId()), claim.getNumber());

